"""Render bilingual V10 service pages from reviewed content. No customer data used."""
import json
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parent
PUBLIC=ROOT/'public'
D=json.loads((ROOT/'market/service_excellence_v10.json').read_text())
S=D['services']; B=D['bi']; I=D['industries']

def page(lang,slug,title,desc,body,campaign='direct',request=True):
    fa=lang=='fa'
    def t(en,per):return per if fa else en
    home='/studio-fa.html' if fa else '/'
    other='en' if fa else 'fa'
    nav=''.join(f'<a href="{url}">{e(label)}</a>' for url,label in [(home,t('Home','خانه')),(f'/services-{lang}.html',t('Services','خدمات')),(f'/industry-{lang}.html',t('Industries','صنایع')),(f'/work-{lang}.html',t('Sample work','نمونه خروجی')),(f'/about-{lang}.html',t('About','درباره ما'))])
    form=f'''<section class="section intake" id="contact"><div><p class="eyebrow">{t('Discuss your project','گفت‌وگو درباره پروژه')}</p><h2>{t('What would you like to improve?','چه کاری می‌خواهید انجام دهید؟')}</h2><p class="muted">{t('An initial conversation is free. We agree the scope, availability and price before work begins.','گفت‌وگوی اولیه رایگان است. محدوده کار، زمان و قیمت پیش از شروع توافق می‌شود.')}</p></div><form id="intake-form"><div class="fields"><label class="field">{t('Name','نام')}<input name="name" required maxlength="120" autocomplete="name"></label><label class="field">{t('Email or phone','ایمیل یا تلفن')}<input name="contact" required maxlength="180"></label></div><input type="hidden" name="service" value="{e(campaign+'|'+title,quote=True)}"><label class="field">{t('Tell us about your business and needs','درباره کسب‌وکار و نیازتان بنویسید')}<textarea name="details" required maxlength="2400"></textarea></label><p class="legal">{t('We use your details to respond to this inquiry. Do not enter sensitive information. This does not confirm a booking or payment.','اطلاعات برای پاسخ به درخواست استفاده می‌شود. اطلاعات حساس وارد نکنید. این درخواست به معنی تأیید رزرو یا پرداخت نیست.')}</p><button id="submit" class="btn">{t('Send inquiry','ارسال درخواست')}</button><div id="request-status" role="status" aria-live="polite" hidden></div></form></section>''' if request else ''
    # Shared script supports the inquiry form; no-form pages only use the navigation controller.
    return f'''<!doctype html><html lang="{lang}" dir="{t('ltr','rtl')}" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(desc,quote=True)}"><title>{e(title)} | Shoreline Digital</title><link rel="stylesheet" href="/agency.css"><link rel="stylesheet" href="/excellence.css"><script defer src="/excellence.js"></script></head><body><a class="skip" href="#main">{t('Skip to content','رفتن به محتوا')}</a><header class="nav"><div class="shell navin"><a class="brand" href="{home}" dir="ltr"><span class="mark">S</span><span>Shoreline<small>DIGITAL</small></span></a><nav class="navlinks">{nav}</nav><div class="controls"><a class="control" href="/{slug}-{other}.html">{t('فارسی','English')}</a><button class="control" id="theme" aria-pressed="false">{t('Dark','تیره')}</button><button class="control navmenu" id="menu" aria-controls="mobilelinks" aria-expanded="false">{t('Menu','منو')}</button><a class="btn navcta" href="{('#contact' if request else home+'#contact')}">{t('Contact us','تماس با ما')}</a></div></div><nav id="mobilelinks" class="shell mobilelinks" hidden>{nav}</nav></header><main id="main" class="shell"><div class="breadcrumb"><a href="{home}">{t('Home','خانه')}</a> / {e(title)}</div><section class="editorial-hero"><p class="eyebrow">{t('Shoreline Digital · Metro Vancouver','شورلاین دیجیتال · ونکوور بزرگ')}</p><h1>{e(title)}</h1><p>{e(desc)}</p><div class="actions"><a class="btn" href="{('#contact' if request else home+'#contact')}">{t('Discuss your project','درباره پروژه‌تان صحبت کنیم')} ↗</a><a class="btn secondary" href="/services-{lang}.html">{t('All services','تمام خدمات')}</a></div></section>{body}{form}</main><footer class="shell foot"><span>Shoreline Digital · Noetfield Systems Inc. · Metro Vancouver</span><a href="/privacy-{lang}.html">{t('Privacy & inquiries','حریم خصوصی و درخواست‌ها')}</a><a href="/{slug}-{other}.html">{t('فارسی','English')}</a></footer></body></html>'''

def box(title,body):
    return f'<article class="detail-box"><h2>{e(title)}</h2><p>{e(body)}</p></article>'
def link(url,label):return f'<a class="textlink" href="{url}">{e(label)} ↗</a>'
def cards(items):
    return '<div class="detail-grid">'+''.join(items)+'</div>'
def card(title,desc,url,label):
    return f'<article class="detail-box"><h3>{e(title)}</h3><p>{e(desc)}</p>{link(url,label)}</article>'
def write(slug,lang,html):
    (PUBLIC/f'{slug}-{lang}.html').write_text(html,encoding='utf-8')
def svc_url(i,lang):return f'/c{i+1:02d}-{lang}.html'
def gen(lang):
    fa=lang=='fa'
    def t(a,b):return b if fa else a
    learn=t('Explore service','جزئیات خدمت')
    title_idx=2 if fa else 1
    for i,s in enumerate(S):
        alias,title,desc=s[0],s[title_idx],s[4 if fa else 3]
        body=cards([box(t('What you receive','خروجی کار'),s[6 if fa else 5]),box(t('What we need from you','اطلاعات مورد نیاز'),s[8 if fa else 7]),box(t('What is outside scope','موارد خارج از محدوده'),s[10 if fa else 9]),box(t('Price and estimated timing','قیمت و زمان تقریبی'),s[11]+' · '+s[12])])
        body+=f'<section class="section"><h2>{t("How delivery is checked","نحوه بررسی تحویل")}</h2><p class="muted">{t("We confirm deliverables and acceptance criteria in writing before work. You receive the agreed output and handover information. Timing depends on scope and access.","خروجی و معیار پذیرش پیش از شروع کتبی توافق می‌شود. خروجی توافق‌شده و اطلاعات تحویل را دریافت می‌کنید. زمان به محدوده و دسترسی بستگی دارد.")}</p><div class="actions">{link("/work-"+lang+".html",t("See sample deliverables","مشاهده نمونه خروجی"))}</div></section>'
        write(f'c{i+1:02d}',lang,page(lang,f'c{i+1:02d}',title,desc,body,alias))
    for i,b in enumerate(B):
        title=b[1 if fa else 0];desc=b[3 if fa else 2];svc=S[b[6]]
        body=cards([box(t('Deliverable','خروجی'),b[5 if fa else 4]),box(t('Research standard','استاندارد تحقیق'),t('Source, observation date, business interpretation, recommendation and confidence. Missing evidence is marked unknown.','منبع، تاریخ مشاهده، تفسیر تجاری، پیشنهاد و میزان اطمینان. شواهد ناموجود به‌عنوان نامشخص ثبت می‌شوند.')),box(t('Required context','اطلاعات مورد نیاز'),svc[8 if fa else 7]),box(t('Scope and pricing','محدوده و قیمت'),t('A standalone research engagement is quoted according to question, geography and depth.','تحقیق مستقل براساس سؤال، محدوده جغرافیایی و عمق کار قیمت‌گذاری می‌شود.'))])
        body+=f'<section class="section">{link("/bi-"+lang+".html",t("All research services","تمام خدمات تحقیق"))} · {link("/work-"+lang+".html",t("Sample report","نمونه گزارش"))}</section>'
        write(f'bi-{i+1:02d}',lang,page(lang,f'bi-{i+1:02d}',title,desc,body,svc[0]))
    for i,b in enumerate(I):
        title=b[1 if fa else 0];desc=b[3 if fa else 2]
        body=cards([box(t('Relevant work','کارهای مرتبط'),b[5 if fa else 4]),box(t('Important considerations','ملاحظات مهم'),b[7 if fa else 6])])
        body+=f'<section class="section"><h2>{t("Where we could start","از کجا می‌توان شروع کرد؟")}</h2>'+cards([card(S[j][title_idx],S[j][4 if fa else 3],svc_url(j,lang),learn) for j in b[8:10]])+'</section>'
        write(f'industry-{i+1:02d}',lang,page(lang,f'industry-{i+1:02d}',title,desc,body,S[b[8]][0]))
    entries=[card(s[title_idx],s[4 if fa else 3],svc_url(i,lang),learn) for i,s in enumerate(S)]
    body=cards(entries)+f'<section class="section"><h2>{t("Specialist research","تحقیق تخصصی")}</h2>{link("/bi-"+lang+".html",t("Explore 12 research services","۱۲ خدمت تخصصی تحقیق"))}</section>'
    write('services',lang,page(lang,'services',t('Our services','خدمات ما'),t('Research, marketing, websites and software — independently scoped around your needs.','تحقیق، بازاریابی، سایت و نرم‌افزار؛ هر خدمت مستقل براساس نیاز شما.'),body))
    write('campaigns',lang,page(lang,'campaigns',t('Specialized services','خدمات تخصصی'),t('Choose the service that addresses your current problem.','خدمت متناسب با مشکل فعلی را انتخاب کنید.'),cards(entries)))
    write('bi',lang,page(lang,'bi',t('Business research and market intelligence','تحقیق و هوشمندی بازار'),t('Understand your customers, competitors and opportunities through documented research.','مشتریان، رقبا و فرصت‌های کسب‌وکارتان را با تحقیق مستند بشناسید.'),cards([card(b[1 if fa else 0],b[3 if fa else 2],f'/bi-{i+1:02d}-{lang}.html',learn) for i,b in enumerate(B)]),'competition'))
    write('industry',lang,page(lang,'industry',t('Industries we serve','صنایع هدف خدمات'),t('Explore practical applications for your type of business.','کاربردهای عملی متناسب با نوع کسب‌وکارتان را بررسی کنید.'),cards([card(b[1 if fa else 0],b[3 if fa else 2],f'/industry-{i+1:02d}-{lang}.html',learn) for i,b in enumerate(I)])))
    write('offers',lang,page(lang,'offers',t('Project pricing and scope','قیمت و محدوده خدمات'),t('Indicative entry prices. No mandatory package or subscription.','قیمت‌های اولیه؛ بدون بسته یا اشتراک اجباری.'),cards([card(S[j][title_idx]+' — '+S[j][11],S[j][6 if fa else 5],svc_url(j,lang),learn) for j in (0,2,3,7)])+f'<p class="muted">{t("Applicable taxes, costs and exact terms confirmed in writing. Other services are individually quoted.","مالیات، هزینه‌ها و شرایط دقیق کتبی تأیید می‌شود. سایر خدمات قیمت توافقی دارند.")}</p>'))
    work=cards([card(t('Agency market comparison','مقایسه آژانس‌های بازار'),t('Actual public-source research sample, not a client engagement.','نمونه تحقیق واقعی از منابع عمومی، نه پروژه مشتری.'),f'/sample-research-{lang}.html',t('Read the report','مطالعه گزارش')),card(t('Website handover example','نمونه تحویل سایت'),t('Illustrative acceptance checklist — not a completed customer project.','چک‌لیست نمونه پذیرش؛ نه پروژه انجام‌شده مشتری.'),f'/sample-handover-{lang}.html',t('See checklist','مشاهده چک‌لیست'))])
    write('work',lang,page(lang,'work',t('Examples of our deliverables','نمونه خروجی خدمات'),t('Review how research and project handover are structured. These are labeled samples, not client testimonials.','ساختار تحقیق و تحویل پروژه را ببینید. این موارد نمونه هستند، نه نظر مشتری یا نمونه‌کار فروخته‌شده.'),work))
    facts=[('Major Tom','https://www.majortom.com/work',t('Publishes project-specific case studies with reported business outcomes.','مطالعات موردی پروژه با نتایج تجاری گزارش‌شده منتشر می‌کند.'),t('Use approved outcome evidence and explain what was measured.','شواهد نتایج مورد تأیید مشتری و روش اندازه‌گیری را ارائه کنید.')),('Nirvana Canada','https://www.nirvanacanada.com/our-services/web-development/',t('Separates web development, portals and ecommerce service capabilities.','قابلیت‌های توسعه وب، پنل و تجارت آنلاین را جداگانه معرفی می‌کند.'),t('Explain scope, platform options and handover for each service.','محدوده، گزینه‌های پلتفرم و تحویل هر خدمت را توضیح دهید.')),('BHP Solution','https://bhpsolution.com/persian-campaign',t('Provides a Persian-specific service path covering website and marketing work.','مسیر اختصاصی فارسی برای خدمات سایت و بازاریابی دارد.'),t('Provide native Persian copy and a bilingual inquiry path.','متن فارسی طبیعی و مسیر درخواست دوزبانه ارائه کنید.'))]
    report=f'<div class="report-note">{t("Research date: 25 November 2026 (Vancouver). Public website observations; no private metrics, commercial relationship or performance comparison is claimed.","تاریخ تحقیق: ۲۵ نوامبر ۲۰۲۶ (ونکوور). مشاهده سایت‌های عمومی؛ بدون ادعای داده خصوصی، رابطه تجاری یا مقایسه عملکرد.")}</div>'+''.join(f'<article class="report-row"><h2>{e(n)}</h2><p>{e(obs)}</p><p><strong>{t("Recommendation","پیشنهاد")}:</strong> {e(rec)}</p><a class="textlink" href="{url}" rel="noopener noreferrer">{t("Source","منبع")} ↗</a></article>' for n,url,obs,rec in facts)
    write('sample-research',lang,page(lang,'sample-research',t('Sample market research: agency service positioning','نمونه تحقیق بازار: جایگاه خدمات آژانس‌ها'),t('A concise comparison of three public competitor websites, with specific actions.','مقایسه کوتاه سه سایت عمومی رقیب همراه با اقدامات مشخص.'),report,'competition'))
    checks=[t('Approved scope, content and business contact information','محدوده، محتوا و اطلاعات تماس تأییدشده'),t('Responsive desktop and mobile layout checked','بررسی چیدمان دسکتاپ و موبایل'),t('Navigation, inquiry submission and error states tested','تست ناوبری، ارسال درخواست و وضعیت خطا'),t('Domain, hosting and account ownership documented','مستندسازی دامنه، میزبانی و مالکیت حساب'),t('Agreed assets, access and support terms handed over','تحویل دارایی، دسترسی و شرایط پشتیبانی توافق‌شده')]
    write('sample-handover',lang,page(lang,'sample-handover',t('Example website handover checklist','نمونه چک‌لیست تحویل سایت'),t('Illustrative acceptance criteria, adapted to each project. No completed client work is implied.','معیارهای نمونه پذیرش، متناسب با هر پروژه. نشانه پروژه انجام‌شده مشتری نیست.'),'<ol class="checklist">'+''.join(f'<li>{e(x)}</li>' for x in checks)+'</ol>','launch'))
    write('about',lang,page(lang,'about',t('About Shoreline Digital','درباره شورلاین دیجیتال'),t('A business technology and digital services brand of Noetfield Systems Inc., serving Metro Vancouver in English and Persian.','برند خدمات فناوری و دیجیتال کسب‌وکار متعلق به Noetfield Systems Inc.، با خدمات فارسی و انگلیسی در ونکوور بزرگ.'),cards([box(t('Our approach','روش همکاری'),t('Understand the business first, agree what is needed, deliver the scoped work and explain the result.','ابتدا کسب‌وکار را می‌شناسیم، درباره نیاز توافق می‌کنیم، کار مشخص را انجام می‌دهیم و نتیجه را توضیح می‌دهیم.')),box(t('Project responsibility','مسئولیت پروژه'),t('A responsible project contact and acceptance criteria are agreed before work. Specialist capacity and timing are confirmed for each engagement.','مسئول ارتباط پروژه و معیار پذیرش پیش از شروع توافق می‌شود. ظرفیت تخصصی و زمان هر همکاری جداگانه تأیید می‌شود.'))])))
    write('privacy',lang,page(lang,'privacy',t('Inquiry information','اطلاعات درخواست'),t('What to know before sending an inquiry.','آنچه پیش از ارسال درخواست باید بدانید.'),cards([box(t('Information requested','اطلاعات دریافتی'),t('Name, contact, service interest and description are stored in our private inquiry system to respond and manage the request.','نام، راه تماس، خدمت موردنظر و توضیحات برای پاسخ و مدیریت درخواست در سیستم خصوصی ثبت می‌شود.')),box(t('Please keep sensitive data out','اطلاعات حساس وارد نکنید'),t('Do not submit passwords, card numbers, patient records or private customer information. Ask us about access, correction or deletion through the contact form.','رمز عبور، شماره کارت، سوابق بیمار یا اطلاعات خصوصی مشتری را ارسال نکنید. درخواست دسترسی، اصلاح یا حذف اطلاعات را از فرم تماس مطرح کنید.'))]),request=False))
    # Preserve old campaign aliases and legacy catalogue without stale pricing.
    for name,idx in [('competition',0),('visibility',1),('automation',5)]:
        write(name,lang,page(lang,name,S[idx][title_idx],S[idx][4 if fa else 3],cards([box(t('Scope','محدوده'),S[idx][6 if fa else 5]),box(t('Pricing','قیمت'),S[idx][11]),box(t('Exclusions','موارد خارج از محدوده'),S[idx][10 if fa else 9])]),S[idx][0]))
    legacy=PUBLIC/('digital-fa.html' if fa else 'digital.html')
    legacy.write_text(page(lang,'services',t('Digital services','خدمات دیجیتال'),t('Browse our full service catalogue.','فهرست کامل خدمات را بررسی کنید.'),cards(entries)),encoding='utf-8')

if __name__=='__main__':
    for lang in ('en','fa'):gen(lang)
    print('V10 service pages rendered')
